    private string MaintenanceBeforeReturnAcceptanceGraph(string graph,FieldSelectionReview context,CompanyWorkOrderCompletionQuery query)
    {
        graph=MaintenanceBeforeClosureGraph(graph,context,query);
        var node=JsonNode.Parse(graph)!.AsObject();var instance=MaintenanceGraphInstance(graph);var approvals=MaintenanceGraphRows<PROCESS_APPROVAL>(node,"Approvals").Where(row=>row.APPROVAL_TYPE=="RETURN_TO_SERVICE").ToArray();var histories=MaintenanceGraphRows<PROCESS_HISTORY>(node,"History").Where(row=>row.EVENT_TYPE=="PHYSICAL_RETURN_ACCEPTED").ToArray();
        if(!instance.ProcessData.Data.TryGetValue(ReturnAcceptanceKey,out var retained)){if(approvals.Length!=0 || histories.Length!=0)throw new InvalidOperationException("Uncorrelated physical return audit cannot establish a prior graph.");return graph;}
        var proof=JsonSerializer.Deserialize<ReturnAcceptanceEvidence>(JsonSerializer.Serialize(retained))??throw new InvalidOperationException("Original return acceptance proof is unavailable.");proof.Command.Require();var command=proof.Command;var stage=command.Review.Assignment.Stage;
        if(stage.Context.Company!=context.Company || stage.Context.Database!=context.Database || command.Reference().Query!=query || proof.Approval.ROW_CREATED_DATE is not {} utc || utc.Kind!=DateTimeKind.Utc || utc<command.Review.Completion.ComparedAtUtc || utc<command.ReturnedAtUtc || approvals.Length!=1 || histories.Length!=1 || proof.Delta is null || proof.Delta.EvidenceKey!=ReturnAcceptanceKey || proof.Delta.BeforeRevision!=stage.ProcessRevision ||
            JsonSerializer.Serialize(proof.Approval)!=JsonSerializer.Serialize(ReturnAcceptanceApproval(command,utc)) || JsonSerializer.Serialize(proof.History)!=JsonSerializer.Serialize(ReturnAcceptanceHistory(command,utc)) || JsonSerializer.Serialize(approvals[0])!=JsonSerializer.Serialize(proof.Approval) || JsonSerializer.Serialize(histories[0])!=JsonSerializer.Serialize(proof.History))throw new InvalidOperationException("Original physical return approval/history/company/actor/UTC/source correlations differ.");
        var changes=proof.Delta.Changes;if(changes.Count!=3 || changes.Count(change=>change.Section=="Process" && change.Id==stage.Task.InstanceId && change.Before is not null)!=1 || changes.Count(change=>change.Section=="Approvals" && change.Id==command.ApprovalId() && change.Before is null)!=1 || changes.Count(change=>change.Section=="History" && change.Id==command.HistoryId() && change.Before is null)!=1)throw new InvalidOperationException("Physical return decision delta differs from its exact process update and immutable approval/history appends.");
        var before=RestoreMaintenanceDelta(graph,proof.Delta);var original=JsonNode.Parse(before)!.AsObject();var originalInstance=MaintenanceGraphInstance(before);
        if(originalInstance.Status!=ProcessStatus.IN_PROGRESS || originalInstance.CurrentStepId!=stage.StepId || originalInstance.StepInstances.Single(row=>row.StepInstanceId==stage.StepInstanceId) is not {Status:StepStatus.PENDING,RequiredRole:var role} || role!=stage.AssignedRole)throw new InvalidOperationException("Original configured return approval assignment changed.");
        var expected=original["Process"]!.Deserialize<PROCESS_INSTANCE>()!;expected.ROW_CHANGED_BY=stage.Context.ActorUserId;expected.ROW_CHANGED_DATE=utc;
        var normalized=MaintenanceDeltaGraph(graph,ReturnAcceptanceKey);var expectedGraph=JsonNode.Parse(before)!.AsObject();expectedGraph["Process"]=JsonSerializer.SerializeToNode(expected);
        if(!JsonNode.DeepEquals(normalized["Process"],MaintenanceDeltaGraph(expectedGraph.ToJsonString(),ReturnAcceptanceKey)["Process"]))throw new InvalidOperationException("Physical return acceptance changed undeclared native process fields.");return before;
    }
    private async Task<CompanyMaintenanceReturnAssignment> ReadReturnAssignmentCore(FieldSelectionReview context,CompanyWorkOrderCompletionQuery query,Func<string?,Task> authority,bool owned)
    {
        query.Require();var source=_editor.GetDataSource(_connectionName)??throw new InvalidOperationException("Original return assignment source is unavailable.");
        async Task Guard(string? role){if(owned)PPDMDataSourceTransaction.RequireOwned(source,IsolationLevel.Serializable);else PPDMDataSourceTransaction.RequireIdle(source);await authority(role);if(!ReferenceEquals(source,_editor.GetDataSource(_connectionName)))throw new InvalidOperationException("Original return assignment binding changed.");}
        await Guard(null);var owner=await ReadExecutionHandoffOwner(context,query.Task);if(owner.Instance.ProcessData.Data.ContainsKey(ReturnAcceptanceKey))throw new InvalidOperationException("Physical return acceptance is already recorded; recover its original reference.");
        var stage=await ReviewReturnAssignedStageAsync(context,query.Task,Guard);var first=await ReadReturnHandoffEvidence(context,query,false,Guard);var closing=await ReadReturnHandoffEvidence(context,query,false,Guard);
        if(JsonSerializer.Serialize(first)!=JsonSerializer.Serialize(closing) || stage.StepInstanceId!=closing.Command.Review.NextStepInstanceId)throw new InvalidOperationException("Original configured return handoff changed during assignment observation.");
        var result=new CompanyMaintenanceReturnAssignment(stage,closing.Command.Review.Decision,closing.History.PROCESS_HISTORY_ID,closing.History.ROW_CREATED_DATE!.Value,ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(closing)));result.Require();await Guard(stage.AssignedRole);return result;
    }
    public Task<CompanyMaintenanceReturnAssignment> ReadReturnAssignmentAsync(FieldSelectionReview context,CompanyWorkOrderCompletionQuery query,Func<string?,Task> authority)=>ReadReturnAssignmentCore(context,query,authority,false);
    private async Task<ReturnAcceptanceEvidence?> ReadReturnAcceptanceEvidence(FieldSelectionReview context,CompanyWorkOrderCompletionQuery query,bool privateRead)
    {
        var owner=await ReadExecutionHandoffOwner(context,query.Task);var graph=await MaintenanceAcceptanceNativeGraph(query.Task.InstanceId,owner.Start.ProcessId);var snapshot=JsonNode.Parse(graph)!.AsObject();var approvals=MaintenanceGraphRows<PROCESS_APPROVAL>(snapshot,"Approvals").Where(row=>row.APPROVAL_TYPE=="RETURN_TO_SERVICE").ToArray();
        if(privateRead && approvals.Length!=0 && (approvals.Length!=1 || approvals[0].APPROVER_USER_ID!=context.ActorUserId || approvals[0].APPROVED_BY!=context.ActorUserId))throw new UnauthorizedAccessException("Original physical return approval belongs to another account before private proof decoding.");
        var before=MaintenanceBeforeReturnAcceptanceGraph(graph,context,query);if(before==graph)return null;var instance=MaintenanceGraphInstance(graph);var proof=JsonSerializer.Deserialize<ReturnAcceptanceEvidence>(JsonSerializer.Serialize(instance.ProcessData.Data[ReturnAcceptanceKey]))!;
        var handoff=await ReadReturnHandoffEvidence(context,query,false,_=>Task.CompletedTask);
        if(proof.Command.Review.Assignment.HandoffRevision!=ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(handoff)) || proof.Command.Review.Assignment.HandoffHistoryId!=handoff.History.PROCESS_HISTORY_ID || proof.Command.Review.Assignment.HandoffAtUtc!=handoff.History.ROW_CREATED_DATE || JsonSerializer.Serialize(proof.Command.Review.Assignment.Verification)!=JsonSerializer.Serialize(handoff.Command.Review.Decision))throw new InvalidOperationException("Original return decision and immutable verification/handoff proof differ.");return proof;
    }
    public async Task<CompanyWorkOrderReturnFacts?> ReadReturnAcceptanceFactsAsync(FieldSelectionReview context,CompanyWorkOrderCompletionQuery query,Func<Task> authority)
    {
        query.Require();var source=_editor.GetDataSource(_connectionName)??throw new InvalidOperationException("Original physical return lifecycle source is unavailable.");async Task Guard(){PPDMDataSourceTransaction.RequireIdle(source);await authority();if(!ReferenceEquals(source,_editor.GetDataSource(_connectionName)))throw new InvalidOperationException("Original return status source changed.");}
        await Guard();var first=await ReadReturnAcceptanceEvidence(context,query,false);await Guard();var closing=await ReadReturnAcceptanceEvidence(context,query,false);if(JsonSerializer.Serialize(first)!=JsonSerializer.Serialize(closing))throw new InvalidOperationException("Original physical return acceptance changed during public observation.");await Guard();return closing is null?null:CompanyWorkOrderReturnFacts.From(ReturnAcceptanceResult(closing));
    }
    private async Task<CompanyWorkOrderReturnRecovery> ReturnAcceptanceReceipt(FieldSelectionReview context,CompanyWorkOrderReturnReference reference,Func<string?,Task> authority)
    {
        var proof=await ReadReturnAcceptanceEvidence(context,reference.Query,true)??throw new InvalidOperationException("Original physical return acceptance is unconfirmed; recovery cannot record it.");if(proof.Command.Reference()!=reference || proof.Command.Review.Assignment.Stage.Context.ActorUserId!=context.ActorUserId)throw new UnauthorizedAccessException("Original return acceptance belongs to another account/reference.");await authority(proof.Command.Review.Assignment.Stage.AssignedRole);
        var closing=await ReadReturnAcceptanceEvidence(context,reference.Query,true);if(JsonSerializer.Serialize(proof)!=JsonSerializer.Serialize(closing))throw new InvalidOperationException("Original physical return acceptance changed during recovery.");var result=ReturnAcceptanceResult(proof);result.Require(context.Company,context.ActorUserId,reference);return result;
    }
    public async Task<CompanyWorkOrderReturnRecovery> RecoverReturnAcceptanceAsync(FieldSelectionReview context,CompanyWorkOrderReturnReference reference,Func<string?,Task> authority)
    {
        reference.Require();var source=_editor.GetDataSource(_connectionName)??throw new InvalidOperationException("Original return source is unavailable.");PPDMDataSourceTransaction.RequireIdle(source);await authority(null);var result=await ReturnAcceptanceReceipt(context,reference,authority);await authority(result.Command.Review.Assignment.Stage.AssignedRole);if(!ReferenceEquals(source,_editor.GetDataSource(_connectionName)))throw new InvalidOperationException("Original return acceptance binding changed.");PPDMDataSourceTransaction.RequireIdle(source);return result;
    }
    public async Task<CompanyWorkOrderReturnRecovery> RecordReturnAcceptanceAsync(CompanyWorkOrderReturnCommand original,Func<string?,Task> authority,Func<bool,Task<CompanyWorkOrderReturnReview?>> readEvidence)
    {
        var command=CompanyInventorySourceReview.Copy(original);command.Require();var stage=command.Review.Assignment.Stage;var context=stage.Context;var query=command.Reference().Query;var source=_editor.GetDataSource(_connectionName)??throw new InvalidOperationException("Original return acceptance source is unavailable.");
        async Task Guard(bool owned){if(owned)PPDMDataSourceTransaction.RequireOwned(source,IsolationLevel.Serializable);else PPDMDataSourceTransaction.RequireIdle(source);await authority(stage.AssignedRole);if(!ReferenceEquals(source,_editor.GetDataSource(_connectionName)))throw new InvalidOperationException("Original return acceptance source changed.");}
        await Guard(false);var existing=await ReadReturnAcceptanceEvidence(context,query,true);if(existing is not null){if(JsonSerializer.Serialize(existing.Command)!=JsonSerializer.Serialize(command))throw new InvalidOperationException("Original physical return acceptance exists with another body/intent.");return await RecoverReturnAcceptanceAsync(context,command.Reference(),authority);}
        async Task Source(bool owned){var current=await readEvidence(owned);if(!owned && current is null || current is not null && (current.SourceRevision()!=command.Review.SourceRevision() || current.Completion.ComparedAtUtc<command.ReturnedAtUtc))throw new InvalidOperationException("Original current work/return inspection/person evidence changed before acceptance.");}
        async Task Stage(bool owned){await Guard(owned);var current=await ReadReturnAssignmentCore(context,query,authority,owned);if(JsonSerializer.Serialize(current)!=JsonSerializer.Serialize(command.Review.Assignment))throw new InvalidOperationException("Original configured return assignment/handoff changed.");}
        await Source(false);await Stage(false);await PPDMDataSourceTransaction.ExecuteAsync(source,async()=>
        {
            await Source(true);await Stage(true);var owner=await ReadExecutionHandoffOwner(context,query.Task);var before=await MaintenanceAcceptanceNativeGraph(query.Task.InstanceId,owner.Start.ProcessId);if(ProcessDefinitionRevision.FromJson(before)!=stage.ProcessRevision)throw new InvalidOperationException("Original reviewed return graph changed.");var utc=DateTime.UtcNow;if(utc<command.Review.Completion.ComparedAtUtc || utc<command.ReturnedAtUtc)throw new InvalidOperationException("Return decision UTC precedes its source comparison.");
            var approval=ReturnAcceptanceApproval(command,utc);var history=ReturnAcceptanceHistory(command,utc);await MaintenanceDecisionWriter(approval,null,"PROCESS_APPROVAL","PROCESS_APPROVAL_ID",context.ActorUserId,PPDMRowMutation.Insert,()=>Guard(true)).InsertAsync(approval,context.ActorUserId);await MaintenanceDecisionWriter(history,null,"PROCESS_HISTORY","PROCESS_HISTORY_ID",context.ActorUserId,PPDMRowMutation.Insert,()=>Guard(true)).InsertAsync(history,context.ActorUserId);
            var previous=CompanyInventorySourceReview.Copy((PROCESS_INSTANCE)(await GetProcessInstanceRepository().GetAsync(Key("PROCESS_INSTANCE_ID",query.Task.InstanceId))).Single());var row=CompanyInventorySourceReview.Copy(previous);row.ROW_CHANGED_BY=context.ActorUserId;row.ROW_CHANGED_DATE=utc;var after=JsonNode.Parse(await MaintenanceAcceptanceNativeGraph(query.Task.InstanceId,owner.Start.ProcessId))!.AsObject();after["Process"]=JsonSerializer.SerializeToNode(row);var delta=CaptureMaintenanceDelta(ReturnAcceptanceKey,before,after.ToJsonString());owner.Instance.ProcessData.Data[ReturnAcceptanceKey]=new ReturnAcceptanceEvidence(command,approval,history,delta);row.INSTANCE_DATA_JSON=JsonSerializer.Serialize(owner.Instance.ProcessData);
            await MaintenanceDecisionWriter(row,previous,"PROCESS_INSTANCE","PROCESS_INSTANCE_ID",context.ActorUserId,PPDMRowMutation.Update,()=>Guard(true)).UpdateAsync(row,context.ActorUserId);await Guard(true);await Source(true);await ReturnAcceptanceReceipt(context,command.Reference(),authority);
        });await Guard(false);await Source(false);return await RecoverReturnAcceptanceAsync(context,command.Reference(),authority);
    }
